+import {Options, RuleType} from '../rules';
+import RuleBuilder, {BooleanOptionBuilder, DropdownOptionBuilder, ExampleBuilder, NumberOptionBuilder, OptionBuilderBase, TextAreaOptionBuilder, TextOptionBuilder} from './rule-builder';
+
+type ListStyle = 'bullet' | 'number';
+type OrderedListStyle = 'always-one' | 'increment';
+
+class AutoTocOptions implements Options {
+  listStyle: ListStyle = 'bullet';
+  bulletMarker: string = '-';
+  orderedListStyle: OrderedListStyle = 'always-one';
+  indentSize: number = 2;
+  minLevel: number = 2;
+  maxLevel: number = 6;
+  title: string = '';
+  useExplicitIds: boolean = false;
+  stripFormattingInToc: boolean = false;
+  excludeHeadings: string[] = [];
+}
+
+type Heading = {level: number, text: string, anchor: string};
+
+const tocStartMarker = /^[ \	]*<!--\\s*toc\\s*-->[ \	]*$/i;
+const tocEndMarker = /^[ \	]*<!--\\s*\\/toc\\s*-->[ \	]*$/i;
+const atxHeading = /^[ \	]{0,3}(#{1,6})(?:[ \	]+(.*?)|[ \	]*)$/;
+
+@RuleBuilder.register
+export default class AutoToc extends RuleBuilder<AutoTocOptions> {
+  constructor() {
+    super({
+      nameKey: 'rules.auto-toc.name',
+      descriptionKey: 'rules.auto-toc.description',
+      type: RuleType.CONTENT,
+    });
+  }
+
+  get OptionsClass(): new () => AutoTocOptions {
+    return AutoTocOptions;
+  }
+
+  apply(text: string, options: AutoTocOptions): string {
+    const newline = text.includes('\\r\
') ? '\\r\
' : '\
';
+    const lines = text.split(/\\r?\
/);
+    const protectedLines = getProtectedLines(lines);
+    const startIndex = lines.findIndex((line, index) => !protectedLines.has(index) && tocStartMarker.test(line));
+
+    if (startIndex === -1) {
+      return text;
+    }
+
+    let endIndex = -1;
+    for (let index = startIndex + 1; index < lines.length; index++) {
+      if (!protectedLines.has(index) && tocEndMarker.test(lines[index])) {
+        endIndex = index;
+        break;
+      }
+    }
+
+    const headings = getHeadings(lines, protectedLines, startIndex, endIndex, options);
+    const toc = buildToc(lines[startIndex], endIndex === -1 ? '<!-- /toc -->' : lines[endIndex], headings, options);
+    const afterTocIndex = endIndex === -1 ? startIndex + 1 : endIndex + 1;
+    const before = lines.slice(0, startIndex);
+    const after = lines.slice(afterTocIndex);
+
+    // The generated region owns the blank line after its end marker.
+    while (after.length > 0 && after[0].trim() === '') {
+      after.shift();
+    }
+
+    return [...before, ...toc, ...after].join(newline);
+  }
+
+  get exampleBuilders(): ExampleBuilder<AutoTocOptions>[] {
+    return [];
+  }
+
+  get optionBuilders(): OptionBuilderBase<AutoTocOptions>[] {
+    return [
+      new DropdownOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.list-style.name', descriptionKey: 'rules.auto-toc.list-style.description', optionsKey: 'listStyle', records: [{value: 'bullet', description: 'Use an unordered list.'}, {value: 'number', description: 'Use an ordered list.'}]}),
+      new TextOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.bullet-marker.name', descriptionKey: 'rules.auto-toc.bullet-marker.description', optionsKey: 'bulletMarker'}),
+      new DropdownOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.ordered-list-style.name', descriptionKey: 'rules.auto-toc.ordered-list-style.description', optionsKey: 'orderedListStyle', records: [{value: 'always-one', description: 'Use 1 for every item.'}, {value: 'increment', description: 'Increment across all items.'}]}),
+      new NumberOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.indent-size.name', descriptionKey: 'rules.auto-toc.indent-size.description', optionsKey: 'indentSize'}),
+      new NumberOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.min-level.name', descriptionKey: 'rules.auto-toc.min-level.description', optionsKey: 'minLevel'}),
+      new NumberOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.max-level.name', descriptionKey: 'rules.auto-toc.max-level.description', optionsKey: 'maxLevel'}),
+      new TextOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.title.name', descriptionKey: 'rules.auto-toc.title.description', optionsKey: 'title'}),
+      new BooleanOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.use-explicit-ids.name', descriptionKey: 'rules.auto-toc.use-explicit-ids.description', optionsKey: 'useExplicitIds'}),
+      new BooleanOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.strip-formatting-in-toc.name', descriptionKey: 'rules.auto-toc.strip-formatting-in-toc.description', optionsKey: 'stripFormattingInToc'}),
+      new TextAreaOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.exclude-headings.name', descriptionKey: 'rules.auto-toc.exclude-headings.description', optionsKey: 'excludeHeadings'}),
+    ];
+  }
+}
+
+function getProtectedLines(lines: string[]): Set<number> {
+  const protectedLines = new Set<number>();
+  let inYaml = lines[0]?.trim() === '---';
+  let inMath = false;
+  let mathDelimiter = '';
+  let codeFence = '';
+
+  for (let index = 0; index < lines.length; index++) {
+    const line = lines[index];
+    if (inYaml) {
+      protectedLines.add(index);
+      if (index > 0 && /^(---|\\.\\.\\.)\\s*$/.test(line)) inYaml = false;
+      continue;
+    }
+    if (codeFence) {
+      protectedLines.add(index);
+      if (new RegExp(`^[ \\\	]*${codeFence[0]}{${codeFence.length},}[ \\\	]*$`).test(line)) codeFence = '';
+      continue;
+    }
+    if (inMath) {
+      protectedLines.add(index);
+      if (line.trim() === mathDelimiter) inMath = false;
+      continue;
+    }
+
+    const fence = line.match(/^[ \	]*(`{3,}|~{3,})/);
+    if (fence) {
+      protectedLines.add(index);
+      codeFence = fence[1];
+    } else if (line.trim() === '$$' || line.trim() === '\\\\[') {
+      protectedLines.add(index);
+      inMath = true;
+      mathDelimiter = line.trim() === '$$' ? '$$' : '\\\\]';
+    }
+  }
+  return protectedLines;
+}
+
+function getHeadings(lines: string[], protectedLines: Set<number>, startIndex: number, endIndex: number, options: AutoTocOptions): Heading[] {
+  const usedAnchors = new Map<string, number>();
+  const headings: Heading[] = [];
+  const tocEnd = endIndex === -1 ? startIndex : endIndex;
+
+  for (let index = 0; index < lines.length; index++) {
+    if (protectedLines.has(index) || (index >= startIndex && index <= tocEnd)) continue;
+    const match = lines[index].match(atxHeading);
+    if (!match) continue;
+    const level = match[1].length;
+    let headingText = (match[2] ?? '').replace(/[ \	]+#+[ \	]*$/, '');
+    const explicitId = headingText.match(/[ \	]*\\{#([^}\\s]+)\\}[ \	]*$/);
+    if (explicitId) headingText = headingText.slice(0, explicitId.index).trimEnd();
+    if (level < options.minLevel || level > options.maxLevel || isExcluded(headingText, options.excludeHeadings)) continue;
+
+    const baseAnchor = options.useExplicitIds && explicitId ? explicitId[1] : makeAnchor(headingText);
+    const count = usedAnchors.get(baseAnchor) ?? 0;
+    usedAnchors.set(baseAnchor, count + 1);
+    headings.push({level, text: headingText, anchor: count === 0 ? baseAnchor : `${baseAnchor}-${count}`});
+  }
+  return headings;
+}
+
+function buildToc(startMarker: string, endMarker: string, headings: Heading[], options: AutoTocOptions): string[] {
+  const toc = [startMarker, ''];
+  if (options.title) toc.push(options.title, '');
+  let itemNumber = 0;
+  for (const heading of headings) {
+    const indent = ' '.repeat(Math.max(0, heading.level - options.minLevel) * Math.max(0, options.indentSize));
+    const marker = options.listStyle === 'number' ? `${options.orderedListStyle === 'increment' ? ++itemNumber : 1}.` : options.bulletMarker;
+    const label = options.stripFormattingInToc ? stripFormatting(heading.text) : heading.text;
+    toc.push(`${indent}${marker} [${label}](#${heading.anchor})`);
+  }
+  if (toc[toc.length - 1] !== '') toc.push('');
+  toc.push(endMarker, '');
+  return toc;
+}
+
+function makeAnchor(text: string): string {
+  return stripFormatting(text)
+      .toLowerCase()
+      .replace(/\\s+/g, '-')
+      .replace(/[^a-z0-9_-]/g, '')
+      .replace(/-+/g, '-')
+      .replace(/^-+|-+$/g, '');
+}
+
+function stripFormatting(text: string): string {
+  return text
+      .replace(/!\\[\\[[^\\]]*\\]\\]/g, '')
+      .replace(/!\\[[^\\]]*\\]\\([^)]*\\)/g, '')
+      .replace(/\\[\\[([^\\]|]+)(?:\\|([^\\]]+))?\\]\\]/g, (_, target: string, display: string) => display ?? target)
+      .replace(/\\[([^\\]]*)\\]\\([^)]*\\)/g, '$1')
+      .replace(/(`+)(.*?)\\1/g, '$2')
+      .replace(/(\\*\\*\\*|___|\\*\\*|__|\\*|_|~~)(.*?)\\1/g, '$2')
+      .replace(/\\\\([\\\\`*{}\\[\\]()#+.!_-])/g, '$1');
+}
+
+function isExcluded(heading: string, exclusions: string[]): boolean {
+  return exclusions.some((exclusion) => {
+    if (exclusion.startsWith('/') && exclusion.endsWith('/') && exclusion.length > 2) {
+      try {
+        return new RegExp(exclusion.slice(1, -1), 'i').test(heading);
+      } catch (_) {
+        return heading.localeCompare(exclusion, undefined, {sensitivity: 'accent'}) === 0;
+      }
+    }
+    return heading.localeCompare(exclusion, undefined, {sensitivity: 'accent'}) === 0;
+  });
+}
